import{c as a,J as l,h as o,k as r}from"./chunks/framework.WgZQdPFo.js";const d=JSON.parse('{"title":"Инвестиционный портфель","description":"Учет ценных бумаг, криптовалютных активов, долей в бизнесе и выданных займов с расчетом доходности P&L и долей распределения.","frontmatter":{"title":"Инвестиционный портфель","description":"Учет ценных бумаг, криптовалютных активов, долей в бизнесе и выданных займов с расчетом доходности P&L и долей распределения.","order":18},"headers":[],"relativePath":"ru/docs/spaces/moy-kapital/investments.md","filePath":"ru/docs/spaces/moy-kapital/investments.md"}'),i={name:"ru/docs/spaces/moy-kapital/investments.md"};function e(s,t,n,p,c,h){return l(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="инвестиционныи-портфель" tabindex="-1">Инвестиционный портфель <a class="header-anchor" href="#инвестиционныи-портфель" aria-label="Permalink to &quot;Инвестиционный портфель&quot;">​</a></h1><p>Вкладка <strong>«Инвестиционный портфель»</strong> предназначена для активов, главной целью которых является сохранение и приумножение капитала: акции и облигации на брокерских счетах, инвестиционные фонды, волатильная криптовалюта, доли в сторонних коммерческих проектах и процентные займы.</p><p>В отличие от простых расчетных счетов, инвестиционный учет в ОмниКрафт ЕРП непрерывно отслеживает финансовый результат ($P&amp;L$) и процентную доходность с учетом валютных колебаний.</p><hr><h2 id="_3-уровневая-архитектура-портфеля" tabindex="-1">3-уровневая архитектура портфеля <a class="header-anchor" href="#_3-уровневая-архитектура-портфеля" aria-label="Permalink to &quot;3-уровневая архитектура портфеля&quot;">​</a></h2><p>Для строгого порядка в инвестициях реализована иерархическая структура из трех уровней:</p><p>$$\\text{Класс активов} \\longrightarrow \\text{Площадка / Брокер} \\longrightarrow \\text{Инструменты}$$</p><ol><li><strong>Класс активов (Категория групп):</strong> верхний уровень распределения рисков («Акции», «Облигации и фонды», «Криптовалюта», «Прямые инвестиции и доли», «Выданные займы»).</li><li><strong>Площадка / Брокер (Группа счетов):</strong> конкретное место размещения капитала («Основной брокер», «Аппаратный криптокошелек», «Венчурный проект №1»).</li><li><strong>Финансовые инструменты (Счета и активы):</strong> конкретные позиции («Акции Сбера», «ОФЗ 26238», «Bitcoin (BTC)», «Доля 25% в мастерской выкроек»).</li></ol><hr><h2 id="полоса-распределения-капитала-allocation-bar" tabindex="-1">Полоса распределения капитала (Allocation Bar) <a class="header-anchor" href="#полоса-распределения-капитала-allocation-bar" aria-label="Permalink to &quot;Полоса распределения капитала (Allocation Bar)&quot;">​</a></h2><p>В верхней части экрана расположена мультисегментная цветная полоса распределения портфеля:</p><ul><li>Каждый сегмент окрашен в цвет соответствующего класса активов.</li><li>Длина сегмента пропорциональна доле класса в общем инвестиционном капитале.</li><li>Наведение курсора на сегмент или клик по элементу легенды показывает точную рублевую стоимость и процентную долю в портфеле.</li></ul><div class="tip custom-block"><p class="custom-block-title">Балансировка рисков</p><p>Грамотно диверсифицированный портфель мастера защищает от спадов в основном бизнесе. Если доля рискованных активов (например, криптовалюты) превышает целевой ориентир, Allocation Bar наглядно это подсветит.</p></div><hr><h2 id="расчет-финансового-результата-p-l-и-долеи-владения" tabindex="-1">Расчет финансового результата (P&amp;L) и долей владения <a class="header-anchor" href="#расчет-финансового-результата-p-l-и-долеи-владения" aria-label="Permalink to &quot;Расчет финансового результата (P&amp;L) и долей владения&quot;">​</a></h2><p>Для каждой инвестиционной позиции программа вычисляет:</p><ul><li><strong>Текущая стоимость в базовой валюте:</strong> фактический рыночный объем актива с учетом актуального курса.</li><li><strong>Финансовый результат ($P&amp;L$):</strong> $$P&amp;L = \\text{Текущая стоимость} - \\text{Вложенный капитал}$$ Положительное значение подсвечивается зеленым цветом, отрицательное — сигнальным красным.</li><li><strong>Процентная доходность:</strong> отношение абсолютного финансового результата к сумме первоначальных инвестиций: $$\\text{Доходность, %} = \\frac{P&amp;L}{\\text{Вложенный капитал}} \\times 100%$$</li><li><strong>Доли владения на всех уровнях:</strong> доля класса активов в заголовке категории, вес площадки в портфеле и доля инструмента в совокупном портфеле (с фиксацией веса внутри брокерского счета).</li></ul><hr><h2 id="добавление-и-настроика-инвестиции" tabindex="-1">Добавление и настройка инвестиций <a class="header-anchor" href="#добавление-и-настроика-инвестиции" aria-label="Permalink to &quot;Добавление и настройка инвестиций&quot;">​</a></h2><p>По кнопке <strong>«Добавить»</strong> открывается окно с двумя сценариями:</p><ol><li><strong>Одиночный актив:</strong> быстрое внесение разового инструмента (например, отдельный договор займа или доля в стартапе).</li><li><strong>Группа / Брокер / Площадка:</strong> пакетное создание портфеля брокера с добавлением нескольких активов через кнопку <strong>«Добавить актив в группу»</strong>.</li></ol><p>В форме указываются:</p><ul><li>Название актива и выбор площадки.</li><li>Класс активов (категория) с возможностью быстрого создания новых классов.</li><li>Валюта инструмента, курс пересчета и вложенная сумма.</li><li>Текущая рыночная оценка.</li><li>Ссылка на терминал / карточку эмитента и заметки по стратегии.</li></ul><hr><h2 id="управление-площадкои-и-сортировка-позиции" tabindex="-1">Управление площадкой и сортировка позиций <a class="header-anchor" href="#управление-площадкои-и-сортировка-позиции" aria-label="Permalink to &quot;Управление площадкой и сортировка позиций&quot;">​</a></h2><p>В карточке каждого брокера доступны инструменты оперативного управления:</p><ul><li><strong>Кнопка «+»:</strong> мгновенное добавление нового инструмента на выбранную площадку.</li><li><strong>Стрелки ↑ / ↓:</strong> перемещение позиций и групп для расстановки приоритетов в списке.</li><li><strong>Кнопка с карандашом (Управление площадкой):</strong> модальное окно для пакетного переименования брокера с каскадным обновлением связанных записей, смены класса активов и исключения закрытых инструментов.</li><li><strong>Переключатель видов («Полосы» / «Плитка»):</strong> быстрый переход между широкой галереей карточек и плотной сводной таблицей.</li></ul>',27)])])}const m=a(i,[["render",e]]);export{d as __pageData,m as default};
